				status = CASE WHEN status = 'paused' THEN 'initializing'::monitor_status ELSE 'paused'::monitor_status END,
				updated_at = NOW()
			 WHERE id = $1 AND team_id = $2
			 RETURNING ${MONITOR_COLUMNS}`,
			[monitorId, teamId]
		);
